import type { On, ToolCallResult } from "claude-code";

const MOD = "classifier-telemetry";
const DIR = ".claude/classifier-telemetry";

interface Verdict {
  decision: string;
  reason: string | null;
  rule: string | null;
  checkedAt: number;
}

interface CallRecord {
  session_id: string;
  tool_use_id: string;
  agent_id: string | null;
  tool: string;
  decision: string | null;
  rule: string | null;
  reason: string | null;
  started_at: number;
  check_ms: number | null;
  duration_ms: number;
  outcome: "ok" | "error" | "deny";
}

function outcomeOf(result: ToolCallResult): CallRecord["outcome"] {
  if (result.deny !== undefined) return "deny";
  if (result.isError) return "error";
  return "ok";
}

/**
 * Writes one record per tool call under `~/.claude/classifier-telemetry/<session>/`.
 * An `ask` verdict goes to the mode's decider, which is the classifier only in auto mode,
 * and the mod API does not expose the mode. `duration_ms` spans the decider plus the tool.
 */
export function register(on: On): void {
  const verdicts = new Map<string, Verdict>();

  on("session.start", async ($, e, next) => {
    const started = await next(e);
    void $.modEvents.emit({ mod: MOD, event: "session.start" });
    return started;
  });

  // Both hooks only observe, so a failure lets the call go on as the engine settled it.
  on("tool.check", async ($, e, next) => {
    const verdict = await next(e);
    if (e.tool_use_id !== undefined) {
      verdicts.set(e.tool_use_id, {
        decision: verdict.decision,
        reason: verdict.reason ?? null,
        rule: verdict.rule ?? null,
        checkedAt: await $.clock.now(),
      });
    }
    return verdict;
  }).catch(($, e, next) => next(e));

  on("tool.call", async ($, e, next) => {
    const startedAt = await $.clock.now();
    let result: ToolCallResult;
    let verdict: Verdict | undefined;
    try {
      result = await next(e);
    } finally {
      verdict = verdicts.get(e.tool_use_id);
      verdicts.delete(e.tool_use_id);
    }
    const [finishedAt, sessionId, home] = await Promise.all([
      $.clock.now(),
      $.session.id(),
      $.env.get("HOME"),
    ]);
    if (home === undefined) return result;

    const record: CallRecord = {
      session_id: sessionId,
      tool_use_id: e.tool_use_id,
      agent_id: e.agentId ?? null,
      tool: e.tool,
      decision: verdict?.decision ?? null,
      rule: verdict?.rule ?? null,
      reason: verdict?.reason ?? null,
      started_at: startedAt,
      check_ms: verdict === undefined ? null : verdict.checkedAt - startedAt,
      duration_ms: finishedAt - startedAt,
      outcome: outcomeOf(result),
    };
    try {
      await $.fs.write(
        `${home}/${DIR}/${sessionId}/${e.tool_use_id}.json`,
        `${JSON.stringify(record)}\n`,
      );
    } catch {
      // A lost record must not fail a call that already ran.
    }
    return result;
  }).catch(($, e, next) => next(e));
}

